'use strict';
let planSignature='';
function renderPlanner(){
 if(!progress||!catalog.length){$('#plan-results').textContent='Collega un salvataggio per pianificare gli sblocchi mancanti.';return;}
 const picker=$('#plan-character');if(!picker.options.length){for(const name of [...new Set(catalog.map(r=>r.character).filter(Boolean))].sort()){const o=document.createElement('option');o.value=o.textContent=name;picker.append(o);}picker.value='Isaac';}
 const goal=$('#plan-goal'),old=goal.value,eligible=catalog.filter(r=>r.character===picker.value&&!unlocked(r));
 const key=JSON.stringify([picker.value,progress.hash,slot,source]);if(goal.dataset.key!==key){goal.innerHTML='<option value="">Tutti gli sblocchi · priorità ai preferiti</option>'+eligible.map(r=>`<option value="${r.id}">${escapeHTML(r.name)}</option>`).join('');goal.value=eligible.some(r=>String(r.id)===old)?old:'';goal.dataset.key=key;}
 const signature=JSON.stringify([key,$('#plan-difficulty').value,[...saved],goal.value]);if(signature===planSignature)return;planSignature=signature;
 const priorities=goal.value?[Number(goal.value),...saved]:[...saved];
 const plan=AtlasPlanner.sequence(catalog,progress.unlocked,picker.value,$('#plan-difficulty').value,priorities);
 const objective=r=>`<button data-detail="${r.id}">${escapeHTML(r.name)}${priorities.includes(r.id)?' · Prioritario':''}<small>${escapeHTML(r.bosses.join(' + ')||'Obiettivo cumulativo')}</small></button>`;
 $('#plan-results').innerHTML=`<div class="planner-overview">${characterIcon(picker.value)}<strong>${escapeHTML(picker.value)} · ${plan.runs.length} run previste</strong><span>${plan.covered.length} sblocchi associati</span></div><p class="meta">Minimo nel modello dei percorsi standard, assumendo vittorie e accessi disponibili. Nessuna stima del tempo o della probabilità di vittoria. Le tappe opzionali saltate possono richiedere altre run; il piano si ricalcola quando il gioco salva.</p>`+plan.runs.map((p,i)=>`<details class="route-plan" ${i===0?'open':''}><summary><strong>${i+1}. ${escapeHTML(p.name)} · ${p.difficulty}</strong><span>${p.rows.length} nuovi sblocchi · ${p.priority} prioritari</span></summary><div class="route-body"><p><strong>Obiettivi del percorso:</strong> ${escapeHTML(p.bosses.join(' → '))}</p>${p.optional.length?`<p><strong>Da aggiungere se possibile:</strong> ${escapeHTML(p.optional.join(' · '))}. Tempi e accessi da rispettare.</p>`:''}<ol>${p.steps.map(s=>`<li>${escapeHTML(s)}</li>`).join('')}</ol><h3>Accessi da verificare</h3><ul>${p.requirements.map(s=>`<li>${escapeHTML(s)}</li>`).join('')}</ul>${p.cumulative.length?'<p>Include ricompense cumulative: richiedono anche le run precedenti della sequenza.</p>':''}<div class="plan-objectives">${p.rows.map(objective).join('')}</div><a href="https://bindingofisaacrebirth.wiki.gg/wiki/${p.source}" target="_blank" rel="noopener noreferrer">Fonte del percorso ↗</a></div></details>`).join('')+(plan.excluded.length?`<details class="route-plan"><summary>${plan.excluded.length} obiettivi da gestire separatamente</summary><p>Condizioni speciali, modalità escluse o azioni non rappresentate nei percorsi. Non conteggiati nelle run previste.</p><div class="plan-objectives">${plan.excluded.map(objective).join('')}</div></details>`:'')+(plan.externalPins.length?`<details class="route-plan"><summary>${plan.externalPins.length} priorità per altri personaggi o sfide</summary><div class="plan-objectives">${plan.externalPins.map(objective).join('')}</div></details>`:'');
}
for(const id of ['plan-character','plan-difficulty','plan-goal'])$('#'+id).addEventListener('change',renderPlanner);
$('#open-planner').addEventListener('click',()=>navigatePage('planner'));
document.addEventListener('click',e=>{const t=e.target.closest('[data-plan]');if(!t)return;const r=catalog.find(r=>r.id===Number(t.dataset.plan));if(!r)return;$('#detail').close();navigatePage('planner');if(r.character)$('#plan-character').value=r.character;$('#plan-difficulty').value='auto';renderPlanner();$('#plan-goal').value=String(r.id);renderPlanner();});
setInterval(renderPlanner,1500);
